export function findServiceDBEntry(
  serviceType: string, 
  category: 'four_wheeler' | 'two_wheeler' | 'Four Wheeler' | 'Two Wheeler',
  customDb?: ServicesDBEntry[]
): ServicesDBEntry {
  const normCategory: 'Four Wheeler' | 'Two Wheeler' = 
    category === 'two_wheeler' || category === 'Two Wheeler' ? 'Two Wheeler' : 'Four Wheeler';
  
  const cleanType = (serviceType || '').trim().toLowerCase();
  const db = customDb && customDb.length > 0 ? customDb : servicesDB;
  
  // Exact match
  const exact = db.find(
    (s) => s.serviceType.toLowerCase() === cleanType && s.vehicleCategory === normCategory
  );
  if (exact) return exact;

  // Exact classification match
  const classMatch = db.find(
    (s) => s.classification.toLowerCase() === cleanType && s.vehicleCategory === normCategory
  );
  if (classMatch) return classMatch;

  // Partial match within same category
  const partial = db.find(
    (s) => (s.serviceType.toLowerCase().includes(cleanType) || cleanType.includes(s.serviceType.toLowerCase())) && s.vehicleCategory === normCategory
  );
  if (partial) return partial;

  // Generic fallback if not category-matched
  const generic = db.find(
    (s) => s.serviceType.toLowerCase().includes(cleanType) || cleanType.includes(s.serviceType.toLowerCase())
  );
  if (generic) return generic;

  // Defaults based on category
  return {
    serviceType: serviceType || 'General Service',
    mileageInterval: normCategory === 'Two Wheeler' ? 3000 : 10000,
    timePeriodMonths: 6,
    vehicleCategory: normCategory,
    classification: 'Periodic Maintanence',
  };
}

export const SERVICES_DB = servicesDB;

